#!/usr/bin/env bash
# GATE M2 — deterministic reprojection.
#
# Proves ggen is a pure function of (ontology.ttl, pack templates), with no
# dependency on what was already sitting on disk. Manufactured provenance is
# signalled per-FILE by the "GENERATED by ggen ... Do not edit." header
# comment (first non-shebang line), never by directory placement -- ggen
# output lives in the same src/, lib/, test/, gleam/, schema/,
# docs/reference/ directories hand-authored code uses. This script finds
# every manufactured file by that marker, deletes exactly those files (never
# a whole directory -- src/beam4pm.app.src and every other hand-authored
# file survives untouched), regenerates, and diffs.
set -euo pipefail
cd "$(dirname "$0")/.."

MARKER="GENERATED by ggen"
SEARCH_DIRS=(src lib test gleam/src gleam/test gleam schema docs/reference)

find_manufactured() {
  # -l: filenames only. -I: skip binary. head -3: marker is always within
  # the first couple of lines (gleam.toml has no comment syntax collision
  # concern; its own header is a TOML comment).
  for d in "${SEARCH_DIRS[@]}"; do
    [ -d "$d" ] || continue
    find "$d" -maxdepth 1 -type f 2>/dev/null
  done | sort -u | while read -r f; do
    head -3 "$f" 2>/dev/null | grep -q "$MARKER" && echo "$f"
  done
}

echo "== pass 1: locating manufactured files by header marker =="
mapfile -t before_files < <(find_manufactured)
echo "found ${#before_files[@]} manufactured files"

echo "== pass 2: sha256 before deletion =="
before_sums="$(for f in "${before_files[@]}"; do shasum -a 256 "$f"; done | sort)"

echo "== pass 3: delete manufactured files, regenerate (both engines) =="
for f in "${before_files[@]}"; do rm -f "$f"; done
rm -f ggen.lock
ggen sync run
# lib/beam4pm_ash.ex, lib/beam4pm_actuation.ex, lib/beam4pm_process_governor.ex
# and their tests are manufactured by the SECOND engine (ggen_igniter, mix
# ggen_igniter.sync), not by the Rust ggen binary -- regenerate those too.
bash scripts/igniter_sync.sh
bash scripts/actuation_sync.sh
bash scripts/process_governor_sync.sh

echo "== pass 4: sha256 after regeneration =="
mapfile -t after_files < <(find_manufactured)
after_sums="$(for f in "${after_files[@]}"; do shasum -a 256 "$f"; done | sort)"

if [ "$before_sums" != "$after_sums" ]; then
  echo "GATE M2: FAIL -- regenerated output differs from the deleted originals" >&2
  diff <(echo "$before_sums") <(echo "$after_sums") >&2 || true
  exit 1
fi

echo "GATE M2: PASS -- ${#after_files[@]} manufactured files byte-identical across delete+regenerate"
